/* ===== jquery-ready-sync (ScenarioWriterCafe) ===== */
// -----------------------------------------------------------------------------
//  jquery-ready-sync.js  (2026-09 jQuery 3 移行時に追加)
//
//  jQuery 3 では jQuery(function($){...}) が DOM 読込済みでも必ず非同期(setTimeout)で
//  実行される。このサイトの ajax/*.js は「jQuery(function($){ 同期 $.ajax }) の直後に
//  結果を読む」書き方を 100 か所以上でしており、非同期だと結果が空のまま先に進んでしまう
//  （ログインできない・一覧が出ない）。jQuery 1 と同じく「読込済みなら即時実行」に戻す。
// -----------------------------------------------------------------------------
(function ($) {
	if (!$ || !$.fn) { return; }
	var origReady = $.fn.ready;
	$.fn.ready = function (fn) {
		if ($.isReady && document.readyState !== 'loading') {
			fn.call(document, $);
			return this;
		}
		return origReady.call(this, fn);
	};
})(window.jQuery);

